def _detect_agentive_context(self, context: str) -> bool:
    agentive_patterns = [
        r'\b(said|asked|replied|whispered|shouted)\b',
        r'\b(walked|ran|stood|turned|looked|smiled)\b',
        r'\b(grabbed|took|held|threw|placed)\b',
    ]
    return any(re.search(p, context.lower()) for p in agentive_patterns)
